// other includes as needed here

// Define the name of the plugin
#ifndef PLUGIN_NAME
#define PLUGIN_NAME "rerun"
#endif

// Load the namespaces
using namespace std;
using json = nlohmann::json;

// Plugin class. This shall be the only part that needs to be modified,
// implementing the actual functionality
#include <deque>
#include <unordered_map>

class RerunnerPlugin : public Sink<json> {
private:
  // Skeleton configuration
  std::vector<std::string> _skeleton_keypoint_paths;
  std::vector<std::string> _keypaths;
  
  // Real-time visualization settings
  std::shared_ptr<rerun::RecordingStream> _rec;
  
  // Multi-skeleton tracking
  std::unordered_map<std::string, std::chrono::steady_clock::time_point> _skeleton_last_update;
  std::unordered_map<std::string, std::chrono::steady_clock::time_point> _skeleton_last_view_update;
  std::unordered_map<std::string, rerun::Color> _skeleton_colors;

  // Rate limiting to prevent gRPC overload
  bool _enable_rate_limiting = true;
  std::chrono::microseconds _min_period_update{100000}; // 100ms default to prevent overload

  // Helper: Generate a consistent color from skeleton ID
  rerun::Color generate_skeleton_color(const std::string& skeleton_id) {
    // Use hash of skeleton_id to generate consistent color
    std::hash<std::string> hasher;
    size_t hash_value = hasher(skeleton_id);
    
    // Use different bits of hash for R, G, B to get varied colors
    uint8_t r = static_cast<uint8_t>((hash_value >> 0) & 0xFF);
    uint8_t g = static_cast<uint8_t>((hash_value >> 8) & 0xFF);
    uint8_t b = static_cast<uint8_t>((hash_value >> 16) & 0xFF);
    
    // Ensure color is not too dark (avoid black or very dark colors)
    r = std::max(r, static_cast<uint8_t>(80));
    g = std::max(g, static_cast<uint8_t>(80));
    b = std::max(b, static_cast<uint8_t>(80));
    
    return rerun::Color(r, g, b);
  }

  

  // Helper function to convert dot notation path to JSON value
  json::json_pointer dot_to_pointer(const std::string &dot_path) {
    std::string result;
    std::string token;
    bool in_brackets = false;
    if (dot_path[0] == '/') 
      return json::json_pointer(dot_path);

    for (char c : dot_path) {
      if (c == '[') {
        if (!token.empty()) {
          result += "/" + token;
          token.clear();
        }
        in_brackets = true;
      } else if (c == ']') {
        if (!token.empty()) {
          result += "/" + token;
          token.clear();
        }
        in_brackets = false;
      } else if (c == '.' && !in_brackets) {
        if (!token.empty()) {
          result += "/" + token;
          token.clear();
        }
      } else {
        token += c;
      }
    }

    if (!token.empty()) {
      result += "/" + token;
    }

    return json::json_pointer(result);
  }

  // Helper function to safely get a value from JSON using dot notation
  std::optional<double> get_numeric_value(const json &j,
                                          const std::string &dot_path) {
    json::json_pointer ptr = dot_to_pointer(dot_path);

    try {
      const auto &value = j[ptr];

      if (value.is_number()) {
        return value.get<double>();
      }
    } catch (const json::exception &e) {
      // Path doesn't exist or other JSON error
    }
    return std::nullopt;
  }

  // Helper: Extract 3D position from JSON keypath
  // Supports both /path/x, /path/y, /path/z AND /path/crd/0, /path/crd/1, /path/crd/2
  std::optional<std::array<double, 3>> extract_3d_position(const json &data, const std::string &keypath) {
      // Try new format first: /JOINT/crd/0, /JOINT/crd/1, /JOINT/crd/2
      auto x_val = get_numeric_value(data, keypath + "/crd/0");
      auto y_val = get_numeric_value(data, keypath + "/crd/1");
      auto z_val = get_numeric_value(data, keypath + "/crd/2");
      
      // Fall back to old format: /path/x, /path/y, /path/z
      if (!x_val) x_val = get_numeric_value(data, keypath + "/x");
      if (!y_val) y_val = get_numeric_value(data, keypath + "/y");
      if (!z_val) z_val = get_numeric_value(data, keypath + "/z");
      
      if (x_val && y_val && z_val) {
          return std::array<double, 3>{*x_val, *y_val, *z_val};
      }
      return std::nullopt;
  }

public:
  RerunnerPlugin() {}

  // Typically, no need to change this
  string kind() override { return PLUGIN_NAME; }

  // Implement the actual functionality here
  return_type load_data(json const &input, string topic = "") override {

    if (topic.empty()) {
      return return_type::error;
    }

    // embed the input json within a parent object named as the topic
    // keep a copy (no move) so we can attempt alternative lookup paths
    json data = json{{topic, input}};

    // TODO: if data contains the "message" field, extract it and use as new data
    
    // Extract agent_id from input (tracker identifier)
    // If not present, use the plugin's agent_id
    std::string agent_id = _agent_id;
    if (input.contains("agent_id")) {
      agent_id = input["agent_id"].get<std::string>();
    }
    
    // get the timestamp from the "ts" field in the input json (IT MUST BE PRESENT)
    uint64_t time_nanoseconds = input["ts"].get<uint64_t>();

    // Update last update timestamp for this skeleton (used for timeout)
    auto prev_skeleton_last_update = _skeleton_last_update[agent_id];
    _skeleton_last_update[agent_id] =  std::chrono::steady_clock::time_point(std::chrono::nanoseconds(time_nanoseconds));
    
    // Continue if _enable_rate_limiting is true and enough time has not passed since last frame
    // or if _enable_rate_limiting is false, skip the rate limiting
    if (_enable_rate_limiting) {

      // Check time since last view update for this skeleton and skip if too soon
      auto time_since_last_view_update = std::chrono::duration_cast<std::chrono::microseconds>(_skeleton_last_update[agent_id] - _skeleton_last_view_update[agent_id]);
      if (time_since_last_view_update < _min_period_update) {
        return return_type::success;
      }
    }

    // Log skeleton visualization if enabled
    std::vector<std::array<float, 3>> joint_positions = {};
    std::vector<uint16_t> keypoint_ids;
    
    // Extract all keypoint positions
    for (size_t i = 0; i < _skeleton_keypoint_paths.size(); ++i) {
      const auto& kp_path = _skeleton_keypoint_paths[i];

      // Build alternative paths to match incoming JSON keys
      const std::string full_path = "/" + topic + "/" + kp_path;        // e.g. /topic/ANKL
      const std::string raw_path = "/" + kp_path;                        // e.g. /ANKL
      const std::string topic_prefixed_no_slash = topic + "/" + kp_path; // e.g. topic/ANKL

      std::optional<std::array<double, 3>> pos;
      pos = extract_3d_position(data, full_path);
      if (!pos) pos = extract_3d_position(data, raw_path);
      if (!pos) pos = extract_3d_position(data, topic_prefixed_no_slash);
        
      if (pos) {
        joint_positions.push_back({static_cast<float>(pos->at(0)), static_cast<float>(pos->at(1)), static_cast<float>(pos->at(2))});
        keypoint_ids.push_back(static_cast<uint16_t>(i));
      }
    }
    
    // Log keypoints with keypoint IDs and class ID only if skeleton is recently updated
    if (!joint_positions.empty()) {

      try {
        // Assign color to skeleton if not already assigned
        if (_skeleton_colors.find(agent_id) == _skeleton_colors.end()) {
          _skeleton_colors[agent_id] = generate_skeleton_color(agent_id);
        }
        
        // Use agent_id in the path to separate different skeletons
        std::string skeleton_path = "skeletons/" + agent_id;
        _rec->log(skeleton_path, 
            rerun::Points3D(joint_positions)
                .with_keypoint_ids(keypoint_ids)
                .with_class_ids({1})
                .with_colors(_skeleton_colors[agent_id])
                .with_radii({15.0f})
                .with_show_labels(false));
      } catch (const std::exception& e) {}
      
    }

    // if we reach here, we will process this frame, so update the last view update time
    _skeleton_last_view_update[agent_id] = _skeleton_last_update[agent_id];

    // Set the current time for this batch of data
    // This is crucial for time series visualization - all subsequent logs will use this timestamp
    _rec->set_time_seconds("time", _skeleton_last_view_update[agent_id].time_since_epoch().count() / 1e9);

    return return_type::success;
  }

  void set_params(void const *params) override {
    // Call the parent class method to set the common parameters
    // (e.g. agent_id, etc.)
    Sink::set_params(params);

    // provide sensible defaults for the parameters
    _params["keypaths"] = json::array();       // empty array by default

    // Configure rate limiting to prevent gRPC overload (enabled by default)
    _enable_rate_limiting = _params.value("enable_rate_limiting", true);

    // then merge the defaults with the actually provided parameters
    _params.merge_patch(*(json *)params);

    // Initialize Rerun with real-time optimized settings
    _rec = std::make_shared<rerun::RecordingStream>("MADS " + _params.value("agent_name", "rerunner (generic)"));
    _rec->spawn().exit_on_failure();

    if (!_agent_id.empty()) {
      _rec->send_recording_name(_agent_id);
    }

    // Auto-configure HPE 16-joint keypoint paths from CSV structure
    // Each joint has format /JOINT_NAME/crd/X for coordinates
    _skeleton_keypoint_paths = {
        "NOS_",  // 0: NOSE
        "NEC_",  // 1: NECK
        "SHOL",  // 2: LEFT_SHOULDER
        "SHOR",  // 3: RIGHT_SHOULDER
        "ELBL",  // 4: LEFT_ELBOW
        "ELBR",  // 5: RIGHT_ELBOW
        "WRIL",  // 6: LEFT_WRIST
        "WRIR",  // 7: RIGHT_WRIST
        "HIPL",  // 8: LEFT_HIP
        "HIPR",  // 9: RIGHT_HIP
        "KNEL",  // 10: LEFT_KNEE
        "KNER",  // 11: RIGHT_KNEE
        "ANKL",  // 12: LEFT_ANKLE
        "ANKR",  // 13: RIGHT_ANKLE
        "EARL",  // 14: LEFT_EAR
        "EARR",  // 15: RIGHT_EAR
    };

    // Define the connections (pairs of landmark indices)
    std::vector<std::pair<uint32_t, uint32_t>> keypoint_connections = {
        {15, 0}, {0, 14},           // head
        {0, 1},                     // neck
        {1, 2}, {2, 4}, {4, 6},     // Left shoulder to left wrist
        {1, 3}, {3, 5}, {5, 7},     // Right shoulder to right wrist
        {1, 8}, {8, 10}, {10, 12},  // Left hip to left ankle
        {1, 9}, {9, 11}, {11, 13},  // Right hip to right ankle
    };

    // Create annotation context with skeleton keypoints and connections
    try {
      std::vector<rerun::AnnotationInfo> annotation_infos;
      for (uint16_t i = 0; i < _skeleton_keypoint_paths.size(); ++i) {
        annotation_infos.push_back(
          rerun::AnnotationInfo(i, _skeleton_keypoint_paths[i], rerun::Rgba32(255, 255, 255))
        );
      }

      // Convert keypoint connections pairs to KeypointPair objects
      std::vector<std::pair<uint16_t, uint16_t>> keypoint_pairs;
      for (const auto& pair : keypoint_connections) {
        keypoint_pairs.push_back({static_cast<uint16_t>(pair.first), static_cast<uint16_t>(pair.second)});
      }

      // Log the AnnotationContext with skeleton description
      // Using log_static to ensure it's logged once for all skeletons
      _rec->log_static(
          "/skeletons",
          rerun::AnnotationContext({rerun::ClassDescription{
              1,
              annotation_infos,
              keypoint_pairs,
          }})
      );
    } catch (const std::exception& e) {
      // Log warning but don't fail initialization
      std::cerr << "Warning: Failed to log skeleton annotation context: " << e.what() << std::endl;
    }
    
    

    // Load the keypaths configuration for time series
    _keypaths.clear();
    if (_params.contains("keypaths") && _params["keypaths"].is_array()) {
      for (const auto &path : _params["keypaths"]) {
        if (path.is_string()) {
          _keypaths.push_back(path.get<std::string>());
        }
      }
    }
  }

  // Implement this method if you want to provide additional information
  map<string, string> info() override {
    // return a map of strings with additional information about the plugin
    // it is used to print the information about the plugin when it is loaded
    // by the agent

    return {{"Rerun version", rerun::version_string()},
            {"Keypaths", _keypaths.empty() ? "None" : json(_keypaths).dump()},
            {"Rate limiting",
             _enable_rate_limiting ? "Enabled" : "Disabled"}
          };
  };
};

